                      );

                      return (
                        <div className="max-w-[75%] space-y-2">
                            {activeLink ? (
                              <div className="w-full bg-white border border-zinc-200/80 rounded-[24px] overflow-hidden shadow-sm animate-in zoom-in-95 duration-500">
                                 {!isFile && (
