                        {recentSearches.map((search, i) => (
                          <button 
                            key={i}
                            onClick={() => setSearchQuery(search)}
                            className="w-full flex items-center gap-3 p-3 rounded-xl hover:bg-zinc-50 transition-colors text-sm text-zinc-600 group"
