                          </button>
                        ))}
                      </>
                    ) : (
                      <div className="py-12 text-center">
                        <div className="w-16 h-16 bg-zinc-50 rounded-full flex items-center justify-center mx-auto mb-4">
                          <Search className="text-zinc-300" size={32} />
