    if (isOpen) {
      setTimeout(() => setStep(initialStep), 0);
    }
  }, [isOpen, initialStep]);

  if (!isOpen) return null;

  const nextStep = async () => {
    // If transitioning from step 2 to step 3, we save onboarding as completed in DB
