        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import Loader from "@/components/ui/Loader";
import { AlertCircle,Check } from "lucide-react";
import { useEffect,useState } from "react";

/**
 * POST PICKER COMPONENT
 * Fetches and displays Instagram media for selection.
 */
export default function PostPicker({ automationId, media, loading, error: fetchError, onSelect, selectedPosts, layout = "grid" }) {
  const [selection, setSelection] = useState(selectedPosts || []);

  const togglePost = (postId) => {
    setSelection(prev => 
      prev.includes(postId) 
        ? prev.filter(id => id !== postId) 
        : [...prev, postId]
    );
  };

  useEffect(() => {
    onSelect(selection);
  }, [selection]);

  const isHorizontal = layout === "horizontal";

  if (loading) return (
    <div className="h-64 flex flex-col items-center justify-center bg-white border border-border rounded-[32px]">
      <Loader text="Getting your posts..." />
    </div>
  );

  if (fetchError) return (
    <div className="h-64 flex flex-col items-center justify-center bg-white border border-border rounded-[32px] p-8 text-center">
      <AlertCircle size={32} className="text-red-500 mb-4" />
      <p className="text-sm font-bold text-foreground">Couldn&apos;t load posts</p>
      <p className="text-xs text-zinc-muted mt-1">{fetchError}</p>
    </div>
  );

  return (
    <section className={`bg-white border border-border rounded-[32px] shadow-sm flex flex-col overflow-hidden transition-all duration-500 ${isHorizontal ? 'h-auto max-h-[220px]' : 'h-full'}`}>
      <div className={`p-6 border-b border-border/40 bg-zinc-50/50 flex items-center justify-between shrink-0 ${isHorizontal ? 'py-2 px-6' : ''}`}>
        <div>
           <h2 className={`font-semibold text-foreground tracking-normal ${isHorizontal ? 'text-sm' : 'text-lg'}`}>Pick your Posts</h2>
           {!isHorizontal && <p className="text-[11px] text-zinc-muted font-normal opacity-60">Choose where to auto reply</p>}
        </div>
        {!isHorizontal && (
          <div className="px-3 py-1 bg-foreground/5 border border-border rounded-full text-[9px] font-semibold text-zinc-muted tracking-normal">
             Selection Needed
          </div>
        )}
      </div>

      <div className={`flex-1 no-scrollbar ${isHorizontal ? 'overflow-x-auto overflow-y-hidden p-4' : 'overflow-y-auto p-2 md:p-6 h-[560px]'}`}>
        <div className={`gap-3 ${isHorizontal ? 'flex flex-nowrap' : 'grid grid-cols-2 sm:grid-cols-3 md:grid-cols-3 lg:grid-cols-3'}`}>
          {media.map((post) => {
            const isSelected = selection.includes(post.id);
            return (
              <div 
                key={post.id} 
                onClick={() => togglePost(post.id)}
                className={`relative rounded-xl overflow-hidden cursor-pointer transition-all duration-300 group shrink-0 ${
                  isSelected ? 'ring-4 ring-foreground ring-offset-2' : 'hover:scale-[1.02]'
                } ${isHorizontal ? 'w-24 h-32' : 'aspect-40/50'}`}
              >
                <img 
                  src={(post.media_type === "VIDEO" || post.media_product_type === "REELS") ? (post.thumbnail_url || post.media_url) : post.media_url} 
                  alt={post.caption || "Instagram Post"} 
                  className={`w-full h-full object-cover transition-all duration-500 ${isSelected ? 'brightness-50' : 'group-hover:brightness-90'}`}
                />
                
                {isSelected && (
                  <div className="absolute inset-0 flex items-center justify-center">
                      <Check className="text-white" size={32} strokeWidth={4} />
                  </div>
                )}

                <div className="absolute bottom-0 left-0 right-0 p-2 bg-gradient-to-t from-black/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity">
                  <p className="text-[8px] text-white font-medium line-clamp-1 truncate">{post.caption || "No caption"}</p>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {!isHorizontal && (
        <div className="p-4 bg-zinc-50 border-t border-border/40 flex items-center justify-between">
            <span className="text-[10px] font-semibold text-zinc-muted tracking-normal">Selection: <span className="text-foreground">{selection.length} Posts</span></span>
            {selection.length > 0 ? (
              <span className="text-[10px] font-semibold text-emerald-600 bg-emerald-50 px-2 py-1 rounded tracking-normal">Targeted rules ready ✨</span>
            ) : (
              <span className="text-[10px] font-semibold text-amber-600 italic tracking-normal">Select at least 1 post to continue</span>
            )}
        </div>
      )}
    </section>
  );
}

"use client";
import { useDashboard } from "@/context/DashboardContext";
import { createClient } from "@/lib/supabase";
import { CreditCard,LogOut,Settings,User,Zap } from "lucide-react";
import { useEffect,useRef,useState } from "react";

export default function ProfileDropdown({ user, realtimeStats, setActiveTab, onAccountSettingsClick, onSubscriptionClick }) {
  const { currentPlan } = useDashboard();
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef(null);
  const supabase = createClient();

  const handleLogout = async () => {
    await supabase.auth.signOut();
    window.location.href = "/login";
  };

  const usedReplies = realtimeStats?.totalDms + realtimeStats?.autoReplies || 0;
  const totalReplies = currentPlan === "free" ? 1000 : currentPlan === "creator_pro" ? 100000 : 1000000;
  const usagePercentage = Math.min(Math.round((usedReplies / totalReplies) * 100), 100);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const avatarUrl = user?.user_metadata?.avatar_url;
  const displayNameForTrigger = user?.user_metadata?.full_name || user?.user_metadata?.name || "Profile";
  const fullNameForDropdown = user?.user_metadata?.full_name || user?.user_metadata?.name || "User Profile";
  const firstLetter = fullNameForDropdown ? (typeof fullNameForDropdown === 'string' ? fullNameForDropdown.charAt(0).toUpperCase() : "U") : "U";

  return (
    <div className="relative" ref={dropdownRef}>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center justify-center p-0.5 bg-white/60 hover:bg-white border border-zinc-200/80 rounded-full transition-all group shrink-0 shadow-sm hover:border-[#6366F1]"
      >
        {avatarUrl ? (
          <img 
            src={avatarUrl} 
            alt={displayNameForTrigger} 
            referrerPolicy="no-referrer"
            className="w-8 h-8 rounded-full object-cover shadow-sm border border-zinc-100"
          />
        ) : (
          <div className="w-8 h-8 bg-[#6366F1]/10 text-[#6366F1] rounded-full flex items-center justify-center font-semibold text-sm shadow-sm border border-zinc-100">
            {firstLetter || <User size={16} />}
          </div>
        )}
      </button>

      {isOpen && (
        <div className="fixed sm:absolute left-1/2 sm:left-auto -translate-x-1/2 sm:translate-x-0 right-auto sm:right-0 top-[64px] sm:top-auto sm:mt-3 w-[calc(100vw-32px)] sm:w-[340px] bg-white border border-zinc-200 rounded-2xl shadow-2xl py-2 z-[999] animate-in fade-in zoom-in-95 duration-200">
          
          <div className="px-5 py-4 border-b border-zinc-200/50 flex items-center gap-3">
            {avatarUrl ? (
              <img 
                src={avatarUrl} 
                alt={fullNameForDropdown} 
                referrerPolicy="no-referrer"
                className="w-10 h-10 rounded-full object-cover border border-zinc-100 shrink-0 shadow-sm"
              />
            ) : (
              <div className="w-10 h-10 bg-[#6366F1]/10 text-[#6366F1] rounded-full flex items-center justify-center font-semibold text-base border border-zinc-200 shrink-0 shadow-sm">
                {firstLetter || <User size={18} />}
              </div>
            )}
            <div className="min-w-0 flex-1">
              <h4 className="text-base font-semibold text-zinc-900 truncate tracking-tight leading-tight">{fullNameForDropdown}</h4>
              <p className="text-xs text-zinc-500 font-normal truncate mt-0.5">{user?.email}</p>
            </div>
          </div>

          <div className="px-5 py-4 bg-zinc-50/80 border-b border-zinc-200/50">
            <div className="flex items-center justify-between text-xs font-semibold text-zinc-600 capitalize mb-2">
              <span className="flex items-center gap-1.5"><Zap size={14} className="text-[#6366F1] fill-[#6366F1]/10" /> Monthly Usage</span>
              <span className="text-zinc-900 font-semibold">{usagePercentage}%</span>
            </div>
            
            <div className="w-full h-2.5 bg-zinc-100 border border-zinc-200/50 rounded-full overflow-hidden shadow-inner">
              <div 
                className="h-full bg-[#6366F1] rounded-full transition-all duration-500 shadow-sm"
                style={{ width: `${usagePercentage}%` }}
              />
            </div>

            <div className="flex items-center justify-between mt-3 text-xs font-semibold text-zinc-500">
              <span>Plan Limits</span>
              <span className="text-zinc-900 font-semibold">{usedReplies} / {totalReplies} Replies</span>
            </div>
          </div>

          <div className="p-2 space-y-1 border-b border-zinc-200/50">
            {[
              { label: "Account Settings", icon: Settings, desc: "Personal information", action: () => onAccountSettingsClick() },
              { label: "Billing & Plans", icon: CreditCard, desc: "Manage subscription & invoices", action: () => onSubscriptionClick() }
            ].map((item) => (
              <button
                key={item.label}
                onClick={() => { setIsOpen(false); item.action(); }}
                className="w-full flex items-start gap-3 p-3 rounded-2xl hover:bg-white text-left transition-all shadow-sm group border border-transparent hover:border-zinc-200/60"
              >
                <div className="p-2.5 bg-zinc-100 text-zinc-600 rounded-xl group-hover:bg-[#6366F1]/10 group-hover:text-[#6366F1] transition-colors shrink-0 shadow-sm">
                  <item.icon size={16} />
