                               <tr>
                                  <td colSpan="5" className="px-6 py-20 text-center text-zinc-400 font-medium text-xs">
                                     {loadingInvoices ? "Fetching your transaction history..." : "No invoices found. Your purchases will appear here."}
                                  </td>
                                </tr>
                            )}
                         </tbody>
                      </table>
                   </div>
                   <div className="text-center py-6 bg-zinc-50 rounded-[28px] border border-zinc-200/60 border-dashed">
                      <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest">Older invoices are archived. Contact support for assistance.</p>
                   </div>
                </div>
             )}
           </div>
         </div>
       </motion.div>
     </div>
      )}
    </AnimatePresence>
  );
}

"use client";

import { AnimatePresence,motion } from "framer-motion";
import { AlertCircle,ArrowRight,Brain,Calendar,Camera,Check,CircleChevronLeft,Clock,Edit2,Gift,Globe,Loader2,MessageSquare,MousePointer2,Plus,Rocket,Send,Sparkles,Star,Trash2,Users,Video,X,Zap } from "lucide-react";
import { useEffect,useState } from "react";
import AutomationPreview from "./AutomationPreview";
import CampaignWizard from "./CampaignWizard";

export default function TriggerManager({ initialTriggers, media = [] }) {
  return (
    <div className="p-6 bg-white/40 backdrop-blur-3xl border border-zinc-200/80 rounded-xl shadow-xl w-full max-w-[1400px] mx-auto">
      <h2 className="text-xl font-black text-[#6366F1] tracking-tight">Trigger Manager</h2>
    </div>
