}

export function TriggerInputModal({ isOpen, onClose, onSelect, currentPlan = "free" }) {
  const [campaignName, setCampaignName] = useState("");
  const [selectedTemplate, setSelectedTemplate] = useState("comment_dm");

  if (!isOpen) return null;
  const handleCreate = () => {
    if (!campaignName.trim()) return;
    onSelect(selectedTemplate, campaignName.trim());
  };

  const strategies = [
    { 
      id: "comment_dm", 
      title: "Comment & DM Automator", 
      desc: "Send a DM and reply to comments when someone uses a keyword.",
      icon: MessageSquare,
      color: "text-blue-600",
      bg: "bg-blue-50",
      isPremium: false
    },
    { 
      id: "faq_assistant", 
      title: "AI FAQ Assistant", 
      desc: "Let AI automatically answer common questions about your products.",
      icon: Sparkles,
      color: "text-purple-600",
      bg: "bg-purple-50",
      isPremium: true,
      isAI: true
    },
    { 
      id: "sales_closer", 
      title: "AI Sales Closer", 
      desc: "Advanced AI that understands intent and works to close deals for you.",
      icon: Rocket,
      color: "text-emerald-600",
      bg: "bg-emerald-50",
      isPremium: true,
      isAI: true
    },
    { 
      id: "story_automator", 
      title: "Story Automator", 
      desc: "Auto-reply to Story mentions & replies with keywords or AI.",
      icon: Camera,
      color: "text-orange-600",
      bg: "bg-orange-50",
      isPremium: true
    }
  ];

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-zinc-950/40 backdrop-blur-xl" 
          />
          
          <motion.div 
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            className="relative w-full max-w-xl bg-white border border-zinc-200/60 rounded-[28px] shadow-2xl p-5 sm:p-8 flex flex-col max-h-[92vh] sm:max-h-[85vh] gap-6"
          >
            <div className="flex items-center justify-between border-b border-zinc-100 pb-4 shrink-0">
              <div>
                <h2 className="text-2xl sm:text-3xl font-medium text-zinc-950 tracking-tighter">Create New Campaign</h2>
                <p className="text-xs font-semibold text-zinc-400 mt-1">Set up automated reply rules</p>
              </div>
              <button 
                onClick={onClose} 
                className="p-2.5 rounded-xl text-zinc-400 hover:text-zinc-950 transition-all cursor-pointer"
              >
                <X size={20} />
              </button>
            </div>

            <div className="overflow-y-auto overflow-x-hidden py-1 px-0.5 flex-1 space-y-5 min-h-0 no-scrollbar">
              <div className="space-y-3">
                <label className="text-[12px] font-medium text-zinc-400 ml-1">Campaign Title</label>
                <input 
                  type="text" 
                  placeholder="e.g. Summer Giveaway Campaign" 
                  value={campaignName} 
                  onChange={(e) => setCampaignName(e.target.value)} 
                  className="w-full bg-zinc-50 border border-zinc-200 rounded-xl px-5 py-3.5 text-sm font-medium text-black placeholder:text-zinc-400 focus:border-[#6366F1] focus:bg-white outline-none transition-all"
                />
              </div>

              <div className="space-y-4">
                <label className="text-[12px] font-bold text-zinc-400 ml-1">Select Your Goal</label>
                <div className="grid grid-cols-2 gap-3">
                  {strategies.map((t) => {
                    // TEMP UNLOCK: isLocked set to false for limited time promotion
                    const isLocked = false; 
                    const isPromoFree = t.isPremium;
                    
                    return (
                      <div 
                        key={t.id} 
                        onClick={() => {
                          setSelectedTemplate(t.id);
                          if (!campaignName.trim()) {
                            setCampaignName(t.title);
                          }
                        }} 
                        className={`group relative border-2 rounded-2xl p-4 flex flex-col items-center text-center gap-3 transition-all duration-300 ${selectedTemplate === t.id ? 'border-[#6366F1] bg-[#6366F1]/5 shadow-lg shadow-[#6366F1]/10 cursor-pointer' : 'border-zinc-100 bg-zinc-50/50 hover:border-zinc-200 hover:bg-white cursor-pointer hover:-translate-y-0.5'}`}
                      >
                        <div className={`w-11 h-11 rounded-xl flex items-center justify-center transition-all duration-500 ${selectedTemplate === t.id ? 'bg-[#6366F1] text-white shadow-xl shadow-[#6366F1]/20 rotate-6' : `${t.bg} ${t.color}`}`}>
