                  <X size={20} />
                </button>
              </div>

              {/* Order Summary & Pricing */}
              <div className="space-y-6">
                <div className="p-5 bg-zinc-50 border border-zinc-200/80 rounded-2xl flex items-center justify-between shadow-xs">
