                      <span className="text-xs font-bold text-emerald-800 block">
                        🎉 Promo Code &apos;{appliedPromo.code}&apos; Applied! ({appliedPromo.discountPercent}% Off)
                      </span>
                      <p className="text-[10px] text-emerald-700/80 mt-0.5 leading-normal">
